    @Test void embeddingRerankAndIntentRouterRecordTypedModelFailures(){var beans=new org.springframework.beans.factory.support.StaticListableBeanFactory();ModelHealthStore local=new ModelHealthStore(beans.getBeanProvider(org.springframework.jdbc.core.JdbcTemplate.class),30);beans.addBean("health",local);var provider=beans.getBeanProvider(com.modelrag.common.model.ModelHealthRegistry.class);var embedding=new com.modelrag.indexing.service.EmbeddingService(new com.modelrag.common.cache.EmbeddingCache(),true,"http://127.0.0.1:9","typed-embedding",tokens,provider);embedding.embed(1,"typed failure 1");embedding.embed(1,"typed failure 2");embedding.embed(1,"typed failure 3");assertEquals("OPEN",local.state(ModelType.EMBEDDING,"ollama-embedding-typed-embedding").state());var reranker=new com.modelrag.search.reranker.HttpReranker(true,"http://127.0.0.1:9",new ObjectMapper(),tokens,provider);var candidates=List.of(new com.modelrag.search.dto.ScoredChunk(1,"证据",.8,"rrf",1));reranker.rerank(1,"问题1",candidates);reranker.rerank(1,"问题2",candidates);reranker.rerank(1,"问题3",candidates);assertEquals("OPEN",local.state(ModelType.RERANK,"http-reranker-http://127.0.0.1:9").state());ComplexityRouter routed=new ComplexityRouter(true,"http://127.0.0.1:9",new ObjectMapper(),provider);routed.route("普通问题一");routed.route("普通问题二");routed.route("普通问题三");assertEquals("OPEN",local.state(ModelType.ROUTER,"http-router-http://127.0.0.1:9").state());}
