    @Test void modelCandidatePolicyDisablesAndPrioritizesRuntimeClients(){var provider=new org.springframework.beans.factory.support.StaticListableBeanFactory().getBeanProvider(JdbcTemplate.class);ModelHealthStore local=new ModelHealthStore(provider);ModelClient primary=new ModelClient(){public String name(){return "policy-primary";}public ModelType type(){return ModelType.CHAT;}public String execute(String input){return "primary";}};ModelClient fallback=new ModelClient(){public String name(){return "policy-fallback";}public ModelType type(){return ModelType.CHAT;}public String execute(String input){return "fallback";}};local.saveCandidate("CHAT","policy-primary","local",100,false,0);local.saveCandidate("CHAT","policy-fallback","local",0,true,0);assertEquals("fallback",new ModelRouter(List.of(primary,fallback),local).execute(ModelType.CHAT,"q"));local.saveCandidate("CHAT","policy-primary","local",100,true,0);assertEquals("primary",new ModelRouter(List.of(fallback,primary),local).execute(ModelType.CHAT,"q"));}
