    @Test void agentInjectsLongTermMemoryIntoQaTrace(){long dataset=store.createDataset("长期记忆注入库","",512,64).id();Document doc=store.addDocument(dataset,"memory.md","MD","memory-doc","员工每年有 5 个工作日带薪年假。");indexing.index(doc.id());memory.upsert(new LongTermMemoryService.Memory("agent-user","PREFERENCE","回答偏好：年假问题使用一句话回答",.9,.9,null));AgentResult result=agent.execute(new QaRequest(dataset,"年假有几天",null,"agent-user"));assertEquals("DONE",result.status());assertTrue(qa.traces().stream().anyMatch(trace->String.valueOf(trace.get("query")).contains("长期记忆")&&String.valueOf(trace.get("query")).contains("一句话回答")));}
