    @Test void conversationsAreIsolatedByUser(){long alice=conversations.create("alice",null,"alice-chat");long bob=conversations.create("bob",null,"bob-chat");conversations.append(alice,"user","alice secret");conversations.append(bob,"user","bob secret");assertTrue(conversations.conversations("alice",false).stream().anyMatch(c->c.id()==alice));assertTrue(conversations.conversations("alice",false).stream().noneMatch(c->c.id()==bob));assertTrue(conversations.history("alice",alice,1,10).stream().anyMatch(e->e.content().contains("alice secret")));assertTrue(conversations.history("bob",alice,1,10).isEmpty());conversations.archive("bob",alice);assertTrue(conversations.conversations("alice",false).stream().anyMatch(c->c.id()==alice));conversations.archive("alice",alice);assertTrue(conversations.conversations("alice",false).stream().noneMatch(c->c.id()==alice));assertTrue(conversations.conversations("alice",true).stream().anyMatch(c->c.id()==alice));}
    @Test void conversationHistoryKeepsAnswerTraceModeAndDataset(){long dataset=store.createDataset("历史元数据库","",512,64).id();Document doc=store.addDocument(dataset,"history-meta.md","MD","history-meta","年假规则是每年五天。远程办公要求部门负责人确认。");indexing.index(doc.id());long ragConversation=conversations.create("history-user",null,"rag-history");qa.answer(new QaRequest(dataset,"年假规则是什么",ragConversation,"history-user"));var ragAssistant=conversations.history("history-user",ragConversation,1,10).stream().filter(entry->"assistant".equals(entry.role())).findFirst().orElseThrow();assertEquals("rag",ragAssistant.mode());assertEquals("历史元数据库",ragAssistant.datasetName());assertNotNull(ragAssistant.traceId());long agentConversation=conversations.create("history-user",null,"agent-history");agent.execute(new QaRequest(dataset,"对比年假规则以及远程办公要求",agentConversation,"history-user"));var entries=conversations.history("history-user",agentConversation,1,10);assertEquals(2,entries.size());assertEquals("对比年假规则以及远程办公要求",entries.get(0).content());assertEquals("agent",entries.get(1).mode());assertEquals("历史元数据库",entries.get(1).datasetName());assertNotNull(entries.get(1).traceId());}
