    @Test void intentNodesCanBeUpdatedAndDeleted(){long dataset=storeDataset();IntentNode created=intents.create(new IntentNode(null,dataset,null,"报销","TOPIC","TOOL","knowledge_lookup","费用",1,true));IntentNode updated=intents.update(dataset,created.id(),new IntentNode(created.id(),dataset,null,"合同","TASK","DIRECT",null,"合同审批",20,true));assertEquals("合同",updated.name());assertEquals("DIRECT",intents.match(dataset,"合同审批怎么处理").orElseThrow().targetType());intents.delete(dataset,created.id());assertTrue(intents.match(dataset,"合同审批怎么处理").isEmpty());assertThrows(IllegalArgumentException.class,()->intents.update(dataset,created.id(),updated));assertThrows(IllegalArgumentException.class,()->intents.delete(dataset,created.id()));}
    @Test void executorValidatesRetriesAndReusesResults(){ResilientToolExecutor executor=new ResilientToolExecutor(new ToolCallValidator());ToolDefinition tool=new ToolDefinition("test","test","LOW",true);AtomicInteger calls=new AtomicInteger();assertEquals("ok",executor.execute(tool,"q",()->calls.incrementAndGet()==1?throwFailure():"ok").value());assertEquals(2,calls.get());assertTrue(executor.execute(tool,"q",()->"different").reused());assertEquals(2,calls.get());assertThrows(IllegalArgumentException.class,()->executor.execute(tool," ",()->"x"));}
    @Test void executorTimesOutThenRetries(){ResilientToolExecutor executor=new ResilientToolExecutor(new ToolCallValidator(),10);AtomicInteger calls=new AtomicInteger();ToolDefinition tool=new ToolDefinition("slow","slow","LOW",true);IllegalStateException error=assertThrows(IllegalStateException.class,()->executor.execute(tool,"q",()->{calls.incrementAndGet();try{Thread.sleep(100);}catch(InterruptedException ignored){}return "late";}));assertEquals("工具调用超时",error.getMessage());assertEquals(2,calls.get());}
    @Test void executorOpensCircuitAndRejectsUntilProbe(){ResilientToolExecutor executor=new ResilientToolExecutor(new ToolCallValidator(),100,1,60_000,10);ToolDefinition tool=new ToolDefinition("breaker","breaker","LOW",true);AtomicInteger calls=new AtomicInteger();assertThrows(IllegalStateException.class,()->executor.execute(tool,"p1",()->{calls.incrementAndGet();throw new IllegalStateException("down");}));assertEquals("OPEN",executor.circuitState("breaker"));IllegalStateException open=assertThrows(IllegalStateException.class,()->executor.execute(tool,"p2",()->{calls.incrementAndGet();return "late";}));assertEquals("工具熔断中，请稍后重试",open.getMessage());assertEquals(2,calls.get());}
    @Test void executorHalfOpenProbeCanCloseCircuit(){ResilientToolExecutor executor=new ResilientToolExecutor(new ToolCallValidator(),100,1,0,10);ToolDefinition tool=new ToolDefinition("probe-tool","probe-tool","LOW",true);assertThrows(IllegalStateException.class,()->executor.execute(tool,"p1",()->{throw new IllegalStateException("down");}));assertEquals("OPEN",executor.circuitState("probe-tool"));assertEquals("ok",executor.execute(tool,"p2",()->"ok").value());assertEquals("CLOSED",executor.circuitState("probe-tool"));}
    @Test void executorRateLimitsPerTool(){ResilientToolExecutor executor=new ResilientToolExecutor(new ToolCallValidator(),100,3,30_000,1);ToolDefinition tool=new ToolDefinition("limited","limited","LOW",true);assertEquals("ok",executor.execute(tool,"p1",()->"ok").value());IllegalStateException limited=assertThrows(IllegalStateException.class,()->executor.execute(tool,"p2",()->"late"));assertEquals("工具调用限流中，请稍后重试",limited.getMessage());}
