    @Test void agentRunsReactLoopForCompositeQuestion(){long dataset=store.createDataset("ReAct验收库","",512,64).id();Document doc=store.addDocument(dataset,"react.md","MD","react-loop","年假规则是每年五天。远程办公要求部门负责人确认。");indexing.index(doc.id());AgentResult result=agent.execute(new QaRequest(dataset,"对比年假规则以及远程办公要求",null));assertEquals("DONE",result.status());assertTrue(result.steps().contains("PLAN"));assertTrue(result.steps().contains("OBSERVE"));assertTrue(result.steps().contains("ANSWER"));assertTrue(result.steps().stream().filter(step->step.startsWith("ACT:")).count()>=2);var stepTrace=agentStepTracer.list(result.executionId());List<String> phases=stepTrace.stream().map(step->step.phase()).toList();assertTrue(phases.containsAll(List.of("THINK","PLAN","ACT","OBSERVE","ANSWER","DONE")));assertTrue(stepTrace.stream().anyMatch(step->"PLAN".equals(step.phase())&&step.data().contains("plannerMode")&&step.data().contains("reactPhase")&&step.data().contains("THOUGHT")&&step.data().contains("\"maxSteps\":20")));assertTrue(stepTrace.stream().anyMatch(step->"ACT".equals(step.phase())&&step.data().contains("knowledge_lookup")&&step.data().contains("subtask")&&step.data().contains("ACTION")));assertTrue(stepTrace.stream().anyMatch(step->"OBSERVE".equals(step.phase())&&step.data().contains("OBSERVATION")));}
    @Test void autoAgentAnswerExposesTraceAndCitationsInResponseAndHistory(){long dataset=store.createDataset("Agent来源验收库","",512,64).id();Document doc=store.addDocument(dataset,"agent-source.md","MD","agent-source","年假规则是每年五天。远程办公要求部门负责人确认。");indexing.index(doc.id());long conversation=conversations.create("agent-source-user",dataset,"agent-source");AutoQaResult result=auto.answer(new AutoQaRequest("对比年假规则以及远程办公要求",conversation),Set.of(dataset),"agent-source-user");assertEquals(RouteDecision.AGENT,result.route());assertEquals("DONE",result.status());assertFalse(result.traceId()==null||result.traceId().isBlank());assertFalse(result.citations().isEmpty());assertTrue(result.confidence()>0);var entries=conversations.history("agent-source-user",conversation,1,10);var assistant=entries.stream().filter(entry->"assistant".equals(entry.role())).reduce((first,second)->second).orElseThrow();assertEquals("agent",assistant.mode());assertEquals(result.traceId(),assistant.traceId());assertTrue(assistant.citations().contains("\"chunkId\""));}
