    @Test void agentInvokesRegisteredHttpToolWithAuthAndTrace() throws Exception {HttpServer server=HttpServer.create(new InetSocketAddress(0),0);AtomicInteger calls=new AtomicInteger();AtomicReference<String> body=new AtomicReference<>();AtomicReference<String> token=new AtomicReference<>();server.createContext("/tool",exchange->{calls.incrementAndGet();token.set(exchange.getRequestHeaders().getFirst("X-Tool-Token"));body.set(new String(exchange.getRequestBody().readAllBytes(),StandardCharsets.UTF_8));byte[] response="外部工具结果：订单已同步".getBytes(StandardCharsets.UTF_8);exchange.sendResponseHeaders(200,response.length);exchange.getResponseBody().write(response);exchange.close();});server.start();String tool="external_echo_"+System.nanoTime();try{long dataset=storeDataset();tools.register(new ToolDefinition(tool,"外部订单工具","LOW",true,"HTTP","http://127.0.0.1:"+server.getAddress().getPort()+"/tool","X-Tool-Token","secret-token"));intents.create(new IntentNode(null,dataset,null,"外部工具","TOPIC","TOOL",tool,"外部工具",10,true));AgentResult result=agent.execute(new QaRequest(dataset,"请调用外部工具查询订单",null));assertEquals("DONE",result.status());assertTrue(result.answer().contains("外部工具结果"));assertEquals(1,calls.get());assertEquals("secret-token",token.get());assertTrue(body.get().contains("请调用外部工具查询订单"));ToolCallTrace trace=traces.list().stream().filter(item->result.executionId().equals(item.traceId())&&tool.equals(item.toolName())).findFirst().orElseThrow();assertTrue(trace.success());assertTrue(trace.output().contains("外部工具结果"));}finally{try{tools.remove(tool);}catch(Exception ignored){}server.stop(0);}}
